// Builds the bazooka's studio models: the world model a dropped launcher wears on the ground and the
// player model a bot carries. Both are ours - no community pack, no licence to write down - and they are
// generated by SMAK (MIT, `Deoroot/smak`), which writes a GoldSrc .mdl without studiomdl and without
// Blender:
//
//   git clone https://github.com/Deoroot/smak ../_tools/smak
//   docker cp <a cs16-hlds container>:/hlds/cstrike/models/p_ak47.mdl .tmp-stock/p_ak47.mdl
//   node infra/models/build/bazooka.mjs
//
// SMAK is a build tool, not a dependency of the server: it is looked up in SMAK_DIR, then in
// ../_tools/smak beside the repository. The .mdl files it prints go to infra/models/weapons and are
// committed, so a machine without SMAK can still build the image.
//
// Why these shapes: the player model is the stock `p_ak47.mdl` with our launcher swapped into it
// (`swapMesh`), so the engine draws it where it draws a rifle - same bones, same frames, same sequences.
// A hand-written bone table was tried first and put the launcher at the bot's feet: `buildMdl` stores each
// corner in the space of its bone, so the offset that was meant to lift it into the hand was subtracted
// back out and the file came out byte-identical. A world model is one bone and one frame.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, "..", "..", "..");
const smak = pathToFileURL(process.env.SMAK_DIR ?? join(repo, "..", "_tools", "smak")).href;
const out = join(repo, "infra", "models", "weapons");
const stockDir = process.env.STOCK_DIR ?? join(repo, ".tmp-stock");

const { buildMdl, indexed, check, sheet, png, swapMesh } = await import(`${smak}/src/index.mjs`);
const { firearm } = await import(`${smak}/kits/firearmkit.mjs`);

/* The gun itself: one fat launcher tube with a pistol grip under it. Two numbers decide whether it reads as
   a weapon or as two floating pieces, and both are the kit's convention rather than a taste:
   - the kit puts the web of the hand at the origin, so the top of the grip's back edge IS `z = 0`;
   - `receiver.z` is the tube's underside. Leaving it above 0 lifts the tube off the grip and the grip hangs
     in the air (that is what a first version did, with `z: 2.2`).
   So the tube's underside sits on 0 and the grip grows down from it; the check below refuses to write a model
   where it does not. */
const launchTube = {
  preset: "rifle",
  length: 42,
  finish: "gunmetal",
  wear: 0.3,
  magazine: false,
  stock: false,
  receiver: { back: -12, length: 34, height: 4.8, width: 4.8, z: 0, top: "round", port: false, serrations: false },
  // The same radius as the tube's half height, centred on its axis: the barrel continues the tube forward.
  barrel: { length: 6, radius: 2.4, z: 2.4, inset: 0, shroud: false },
  grip: { angle: 18, length: 4.6, depth: 2.2, width: 1.8, checkering: true },
  guard: { length: 2.6, depth: 1.2, thick: 0.2, width: 0.6 },
  forend: false,
  sights: { front: { height: 1.6 }, rear: { height: 1.2 } },
};
const piece = firearm(launchTube);

/* Where the mesh has to sit for the engine to draw it in the hand.
 *
 * Not "at the hand bone's rest position", which is what a previous version tried: `buildMdl` stores every
 * corner in the space of the bone that carries it (it multiplies by the inverse of the bone's rest matrix),
 * so an offset added to the points was subtracted straight back out - the file came out byte-identical and the
 * launcher stayed at the bot's feet. Measured here: `smak info` on the old and the new file was the same
 * model, and the vertex box of the mesh never moved.
 *
 * What is copied instead is the stock carrier: `p_ak47.mdl` is read from the game image and our piece is
 * swapped into it with `swapMesh`. The engine then draws the launcher exactly where it draws an AK - same
 * bones, same frames, same sequences, same bone (`Line02`, the AK's own) - which is the only placement that
 * cannot be argued with. `size: "own"` keeps the 42 units the piece was drawn at and puts its grip where the
 * AK's grip is, `turn: "as drawn"` keeps the kit's axes.
 */
const stockAk = join(stockDir, "p_ak47.mdl");


const boxOf = (tris) => {
  const points = tris.flat().map((corner) => corner.p);
  return [0, 1, 2].map((axis) => [Math.min(...points.map((point) => point[axis])), Math.max(...points.map((point) => point[axis]))]);
};

// The tube on its own - no grip, no guard, no trigger. Its underside is the plane the grip's top is on, so a
// number under 0 is the air the grip would be hanging in, and the whole piece has to reach below it.
const tubeOnly = boxOf(firearm({ ...launchTube, grip: false, guard: false, trigger: false }).tris);
const whole = boxOf(piece.tris);
if (Math.abs(tubeOnly[2][0]) > 0.05)
  throw new Error(`the tube's underside is at z ${tubeOnly[2][0].toFixed(2)} instead of 0: the grip would hang in the air`);
if (whole[2][0] > -1) throw new Error(`the model reaches z ${whole[2][0].toFixed(2)}: it has no grip under the tube`);
console.log(`side view: tube z ${tubeOnly[2][0].toFixed(2)}..${tubeOnly[2][1].toFixed(2)}, grip down to z ${whole[2][0].toFixed(2)}`);

/* The kit paints 1024x512; GoldSrc draws nothing finer than 512 (and 256 on older builds), and every pixel
   of a studio model's texture is stored in the file, so a 1024x512 picture is half a megabyte of nothing. A
   plain box filter halves both sides. */
const shrink = ({ width, height, rgb }) => {
  const wide = width / 2;
  const tall = height / 2;
  const small = new Uint8Array(wide * tall * 3);
  for (let y = 0; y < tall; y++)
    for (let x = 0; x < wide; x++)
      for (let channel = 0; channel < 3; channel++) {
        let sum = 0;
        for (const [dx, dy] of [
          [0, 0],
          [1, 0],
          [0, 1],
          [1, 1],
        ])
          sum += rgb[((y * 2 + dy) * width + (x * 2 + dx)) * 3 + channel];
        small[(y * wide + x) * 3 + channel] = Math.round(sum / 4);
      }
  return { width: wide, height: tall, rgb: small };
};

const texture = indexed(shrink(piece.image), "bazooka_skin.bmp");

/* The world model: what a dropped launcher wears. One bone, one frame - the same shape as w_ak47.mdl.
   The player model is not built from a bone table any more (see `stockAk` above): it is the stock AK with
   our piece swapped in, so the engine has nothing to interpret. */
const weighted = (bone) => piece.tris.map((triangle) => triangle.map((point) => ({ ...point, bone })));

/** A still frame: every bone where its rest pose leaves it, with no turn. */
const still = (bones) => [bones.map((bone) => [...(bone.pos ?? [0, 0, 0]), 0, 0, 0])];

const worldModel = {
  name: "w_bazooka.mdl",
  bones: [{ name: "Line02", parent: -1 }],
  tris: weighted("Line02"),
  fps: 30,
};

mkdirSync(out, { recursive: true });

{
  const spec = worldModel;
  const mdl = buildMdl({
    name: spec.name,
    bones: spec.bones,
    bodyparts: [
      { name: "studio", models: [{ name: spec.name.replace(/\.mdl$/, ""), meshes: [{ tris: spec.tris, texture }] }] },
    ],
    sequences: [{ name: "idle", fps: spec.fps, loops: true, frames: still(spec.bones) }],
  });

  // The check is the gate, not a warning: a model the engine refuses is a model that would precache to
  // nothing and leave the event silent (docs/activities/assets.md, rule 2).
  const report = check(mdl, "goldsrc");
  for (const line of [...report.facts, ...report.warnings.map((w) => `WARN ${w}`), ...report.errors.map((e) => `ERROR ${e}`)])
    console.log(`${spec.name}: ${line}`);
  if (report.errors.length) process.exit(1);

  writeFileSync(join(out, spec.name), mdl);
  console.log(`${join(out, spec.name)} (${mdl.length} bytes)`);
}

/* The player model: the stock AK, repainted. `size: "own"` keeps the piece's 42 units and anchors its grip
   where the AK's grip sits, so the launcher is longer than the rifle it replaces without moving the hand. */
{
  const source = readFileSync(stockAk);
  const { mdl, report } = swapMesh(source, {
    piece: { tris: piece.tris, haft: piece.haft },
    texture,
    size: "own",
    turn: "as drawn",
  });

  for (const line of Object.entries(report).map(([key, value]) => `${key}: ${typeof value === "object" ? JSON.stringify(value) : String(value)}`))
    console.log(`p_bazooka.mdl: ${line}`);
  // The check is the gate here too, and it is run against the stock file: what must not change is the bones,
  // the frames and the sequences the AK carries.
  const verdict = check(mdl, "goldsrc", { source });
  for (const line of [...verdict.facts, ...verdict.warnings.map((w) => `WARN ${w}`), ...verdict.errors.map((e) => `ERROR ${e}`)])
    console.log(`p_bazooka.mdl: ${line}`);
  if (verdict.errors.length) process.exit(1);

  writeFileSync(join(out, "p_bazooka.mdl"), mdl);
  console.log(`${join(out, "p_bazooka.mdl")} (${mdl.length} bytes) carried by ${basename(stockAk)}`);
}

// Pictures for a human: six views of the shape, drawn from the file that was just written rather than from
// the builder, so a picture that looks wrong is a file that is wrong.
const views = sheet(readFileSync(join(out, "p_bazooka.mdl")), {});
writeFileSync(join(out, "bazooka_sheet.png"), png(views.width, views.height, views.rgba));
console.log(`${join(out, "bazooka_sheet.png")} - six views of p_bazooka.mdl, look at it before the image is built`);
